import json, sys, redis, valkey

def client(port):
    if port == 6379:
        return redis.Redis(port=port)
    return valkey.Valkey(port=port)

def type_of(r,k):
    return r.type(k).decode()

def snap_key(r, k):
    t = type_of(r,k)
    ttl = r.pttl(k)
    if t == 'string':
        v = r.get(k)
    elif t == 'list':
        v = r.lrange(k,0,-1)
    elif t == 'set':
        v = sorted(r.smembers(k))
    elif t == 'zset':
        v = r.zrange(k,0,-1,withscores=True)
    elif t == 'hash':
        v = r.hgetall(k)
    elif t == 'stream':
        v = stream_snap(r,k)
    else:
        v = None
    return {'type':t,'ttl':ttl,'value':v}

def stream_snap(r,k):
    info = r.xinfo_stream(k)
    out = {
      'length': info['length'],
      'last-generated-id': info['last-generated-id'].decode(),
      'max-deleted-entry-id': info.get('max-deleted-entry-id',b'0-0').decode(),
      'entries-added': info.get('entries-added'),
      'recorded-first-entry-id': info.get('recorded-first-entry-id',b'0-0').decode(),
      'entries': [(eid.decode(), {kk.decode():vv.decode() for kk,vv in fields.items()}) for eid, fields in r.xrange(k)],
      'groups': [],
    }
    for g in r.xinfo_groups(k):
        gd = {
          'name': g['name'].decode(),
          'last-delivered-id': g['last-delivered-id'].decode(),
          'entries-read': g.get('entries-read'),
          'lag': g.get('lag'),
          'pel-count': g.get('pending'),
          'pending': [],
          'consumers': [],
        }
        # full PEL via XPENDING
        pend = r.xpending_range(k, g['name'], '-', '+', 100000)
        for p in pend:
            gd['pending'].append((p['message_id'].decode(), p['consumer'].decode(), p['times_delivered']))
        gd['pending'].sort()
        for c in r.xinfo_consumers(k, g['name']):
            cd = {
              'name': c['name'].decode(),
              'pel-count': c['pending'],
              'pending': [],
            }
            for p in r.xpending_range(k, g['name'], '-', '+', 100000, consumername=c['name']):
                cd['pending'].append((p['message_id'].decode(), p['times_delivered']))
            cd['pending'].sort()
            gd['consumers'].append(cd)
        gd['consumers'].sort(key=lambda x: x['name'])
        out['groups'].append(gd)
    out['groups'].sort(key=lambda x: x['name'])
    return out

def snapshot(port):
    r = client(port)
    info = r.info('keyspace')
    dbs = sorted(int(k[2:]) for k in info.keys())
    res = {}
    for db in dbs:
        rr = client(port)
        rr.execute_command('SELECT', db)
        keys = sorted(rr.keys('*'))
        res[str(db)] = {k.decode(): snap_key(rr,k) for k in keys}
    return res

if __name__ == '__main__':
    port = int(sys.argv[1]); outp = sys.argv[2]
