import json, sys, base64, redis, valkey

def client(port):
    if port == 6379:
        return redis.Redis(port=port)
    return valkey.Valkey(port=port)

def norm(o):
    if isinstance(o, bytes):
        return {'b': base64.b64encode(o).decode()}
    if isinstance(o, (list, tuple)):
        return [norm(x) for x in o]
    if isinstance(o, dict):
        return {k: norm(v) for k,v in sorted(o.items())}
    return o

def stream_snap(r,k):
    info = r.xinfo_stream(k)
    out = {
      'length': info['length'],
      'last-generated-id': norm(info['last-generated-id']),
      'max-deleted-entry-id': norm(info.get('max-deleted-entry-id',b'0-0')),
      'entries-added': info.get('entries-added'),
      'recorded-first-entry-id': norm(info.get('recorded-first-entry-id',b'0-0')),
      'entries': [(eid.decode(), {kk.decode():norm(vv) for kk,vv in fields.items()}) for eid, fields in r.xrange(k)],
      'groups': [],
    }
    for g in r.xinfo_groups(k):
        gd = {
          'name': g['name'].decode(),
          'last-delivered-id': norm(g['last-delivered-id']),
          'entries-read': g.get('entries-read'),
          'lag': g.get('lag'),
          'pel-count': g.get('pending'),
          'pending': [],
          'consumers': [],
        }
        for p in r.xpending_range(k, g['name'], '-', '+', 100000):
            gd['pending'].append((p['message_id'].decode(), p['consumer'].decode(), p['times_delivered']))
        gd['pending'].sort()
        for c in r.xinfo_consumers(k, g['name']):
            cd = {'name': c['name'].decode(), 'pel-count': c['pending'], 'pending': []}
            for p in r.xpending_range(k, g['name'], '-', '+', 100000, consumername=c['name']):
                cd['pending'].append((p['message_id'].decode(), p['times_delivered']))
            cd['pending'].sort()
            gd['consumers'].append(cd)
        gd['consumers'].sort(key=lambda x: x['name'])
        out['groups'].append(gd)
    out['groups'].sort(key=lambda x: x['name'])
    return out

def snap_key(r, k):
    t = r.type(k).decode()
    ttl = r.pttl(k)
    if t == 'string':
        v = norm(r.get(k))
    elif t == 'list':
        v = norm(r.lrange(k,0,-1))
    elif t == 'set':
        v = sorted(norm(x)['b'] for x in r.smembers(k))
    elif t == 'zset':
        v = [(norm(m)['b'], s) for m,s in r.zrange(k,0,-1,withscores=True)]
    elif t == 'hash':
        v = {kk.decode():norm(vv) for kk,vv in r.hgetall(k).items()}
    elif t == 'stream':
        v = stream_snap(r,k)
    else:
        v = None
    return {'type':t,'ttl':ttl,'value':v}

def snapshot(port):
    r = client(port)
    info = r.info('keyspace')
    dbs = sorted(int(k[2:]) for k in info.keys())
    res = {}
    for db in dbs:
        rr = client(port)
        rr.execute_command('SELECT', db)
        keys = sorted(rr.keys('*'))
        res[str(db)] = {k.decode(): snap_key(rr,k) for k in keys}
    return res

if __name__ == '__main__':
    port = int(sys.argv[1]); outp = sys.argv[2]
    s = snapshot(port)
    with open(outp,'w') as f:
        json.dump(s,f,sort_keys=True,indent=1)
    tot = sum(len(v) for v in s.values())
    print(f"port {port}: dbs={list(s.keys())} total_keys={tot}")
